/* nestly_v723 — CI-100 check 92 (UI/RPC contract validation), business-UI half.
 *
 * docs/design/ci/CI-READER-CONTRACTS.json (generated by scripts/quality/ci-reader-contracts.mjs)
 * is the single machine-readable contract for the 25 public.get_ci_* readers plus
 * get_customer_intelligence_v83 and app.v176_evidence_pack. db/tests/executed/
 * v723_corpus_reader_contracts.sql proves the SQL side (every declared top-level key exists with
 * the declared jsonb_typeof() on a real, minimally-seeded call). This file proves the browser
 * side of the same check, in the tradition tests/platform-console/v667-consultative-payload.
 * test.mjs established: EXECUTE the real renderer (never a hand-copied re-implementation) via
 * vm, against a fixture built from nothing but the contract's declared keys, and separately grep
 * the renderer's own source for every `payload.foo.bar` chain it reads, requiring each to be a
 * path the contract actually declares. A source-regex test that only checks "the string exists
 * somewhere in the file" would not have caught nestly_v667's defect (superseded key names that
 * happened to still appear in a comment); this extracts and executes real code instead.
 *
 * Renderers covered: funnelConversionPanelHtmlV679, demographicsPanelHtmlV679,
 * behaviourPanelHtmlV679, opportunitiesPanelHtmlV685, ciOpportunityCardHtmlV685 (all five are
 * pure top-level functions of their payload — same posture as recoveryReportHtmlV550, per the
 * nestly_v679 header comment above them in app/app.js) and categoryMixMarkupV650 (NOT pure — it
 * reads customerIntelligencePage's own closure state, so it is exercised through a thin,
 * clearly-marked rewrite that substitutes a `bundle` parameter for the closure reads; every
 * substitution is listed at CATEGORY_MIX_REWRITES below so a reviewer can see exactly what was
 * changed and why).
 *
 * GAP CLOSURE (this pass, check 92 §a): four more consuming renderers, same posture as
 * categoryMixMarkupV650 above — each reads its own `lastXBundle`/`lastXError` page-closure
 * state rather than taking a payload parameter, so each is exercised the same way: extract the
 * real source, supply the closure variables (and the small in-page helpers the block calls,
 * e.g. ciQuietErrorV650/ciMeasuredSinceV650) as vm sandbox globals, run it unmodified.
 *   - acquisitionMarkupV650   (public.get_ci_acquisition_v1)
 *   - funnelMarkupV650        (public.get_ci_funnel_v1)
 *   - contactabilityMarkupV650(public.get_ci_contactability_v1)
 *   - ciCategoryCustomersRowsMarkupV650 (public.get_ci_category_customers_v1) — reads a
 *     `categoryCustomersCacheV650.get(nodeKey)` cache entry rather than a bundle directly;
 *     exercised with a real Map holding `{data: <fixture>}`, same idea, one more layer of
 *     indirection.
 * ciOpportunityCardHtmlV685's execution above already calls every nestly_v716 impact-
 * translation helper (ciOpportunityMaterialityChipHtmlV716/ciOpportunityMarginHtmlV716/
 * ciOpportunityCapacityHtmlV716/ciOpportunityRetentionRiskHtmlV716/
 * ciOpportunityConcentrationHtmlV716/ciOpportunityAlternativesListHtmlV716) as plain calls in
 * its own body — no separate wiring needed; a dedicated assertion below checks their markup
 * actually appears in the rendered HTML so this stays proven, not assumed. There are no
 * v719-named helpers anywhere in app/app.js (grepped at the time of this pass) — nothing to add.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import vm from 'node:vm';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const appJs = readFileSync(join(root, 'app', 'app.js'), 'utf8');

const contractsGen = await import(join(root, 'scripts', 'quality', 'ci-reader-contracts.mjs'));
const { CONTRACTS, buildDoc, extractEmbedded, JSON_PATH } = contractsGen;

/* ------------------------------------------------------------ generator/artifact consistency */

