/* --------------------------------------------------------------------- fixture construction */

/* Builds the minimal object a reader's `nested` (or `required`, when nested is empty) contract
   describes — ONLY the keys the contract lists as required (never the ones marked __optional),
   each set to a representative value of its declared type. A "TYPE|null" union always picks the
   non-null branch: the point of this fixture is the renderer's real, populated-data code path,
   not its guard clauses (those are covered by the empty/error states the page's own
   ciEmptyPanelV679 / ciQuietErrorV650 wiring already handles, outside these pure renderers). */
function leafValue(declaredType) {
  const first = declaredType.split('|').find((t) => t !== 'null') || declaredType.split('|')[0];
  switch (first) {
    case 'string': return 'x';
    case 'number': return 1;
    case 'boolean': return true;
    case 'object': return {};
    case 'array': return [];
    default: return null;
  }
}

function buildFixture(nested, requiredTopLevel) {
  const optional = new Set(nested.__optional || []);
  const entries = Object.entries(nested).filter(([k]) => k !== '__optional' && !optional.has(k));
  const root = {};
  // Ensure every top-level required key exists even if `nested` never drills into it.
  for (const [key, type] of Object.entries(requiredTopLevel || {})) {
    if (!(key in root)) root[key] = leafValue(type);
  }
  // Sort shallowest-first so parent containers are established before children are written.
  entries.sort((a, b) => a[0].split('.').length - b[0].split('.').length);
  for (const [path, type] of entries) {
    const segments = path.split('.');
    let cursor = root;
    for (let i = 0; i < segments.length; i++) {
      const seg = segments[i];
      const isLast = i === segments.length - 1;
      if (seg === '*') {
        if (!Array.isArray(cursor)) continue; // contract bug guard; should not happen
        if (cursor.length === 0) cursor.push({});
        cursor = cursor[0];
        continue;
      }
      if (isLast) {
        cursor[seg] = leafValue(type);
      } else {
        const nextIsArrayIndex = segments[i + 1] === '*';
        if (!(seg in cursor) || typeof cursor[seg] !== 'object' || cursor[seg] === null) {
          cursor[seg] = nextIsArrayIndex ? [] : {};
        }
        cursor = cursor[seg];
      }
    }
  }
  return root;
}

/* --------------------------------------------------------------- payload-access extraction */

/* Conservative extractor: walks the renderer source for `root.a.b` / `root?.a?.b` chains where
   `root` is a tracked variable (a function parameter, or a local alias discovered from
   `const x=root.a` / `root.map(x=>...)` / destructuring `const {a,b}=root`), normalizes optional
   chaining and array iteration to the same dotted-path-with-`.*` notation the contract uses, and
   drops any chain whose final segment is a known Array/Object/String prototype method rather than
   a real payload key. Conservative means it can MISS an access (e.g. one reached through a alias
   this heuristic does not model) but every chain it DOES report is a real property read in the
   source — false negatives are possible, false positives are not silently accepted (the assertion
   below fails loudly if a reported path isn't declared, so a miss just means "not yet guarded",
   never a false alarm blocking unrelated work). */
const JS_METHOD_NAMES = new Set([
  'map', 'filter', 'find', 'findIndex', 'some', 'every', 'reduce', 'forEach', 'join', 'slice',
  'length', 'toFixed', 'toString', 'includes', 'indexOf', 'push', 'pop', 'concat', 'sort',
  'replace', 'replaceAll', 'trim', 'split', 'keys', 'values', 'entries', 'has', 'get', 'set',
  'isArray', 'flat', 'flatMap', 'charAt', 'toUpperCase', 'toLowerCase',
]);

/* Joins a base dotted-path (possibly '' for "the root object itself") with further segments,
   without leaving a stray leading dot when base is ''. */
function joinPath(base, segs) {
  return [base, ...segs].filter((s) => s !== '').join('.');
}

/* `rootVarMap` is { varName: basePath }, e.g. {payload:'', item:'ranked.*'} — payload IS the
   contract's root object (basePath ''), item is one element of the ranked array. */
function extractAccesses(source, rootVarMap) {
  const aliases = new Map(Object.entries(rootVarMap));
  // const X = ROOT (bare copy, no property access — e.g. `const p=payload;`)
  for (const m of source.matchAll(/const\s+([a-zA-Z_$][\w$]*)\s*=\s*([a-zA-Z_$][\w$]*)\s*[;,)]/g)) {
    const [, alias, base] = m;
    if (!aliases.has(base) || aliases.has(alias)) continue;
    aliases.set(alias, aliases.get(base));
  }
  // const X = ROOT?.a?.b (alias assignment through a property chain, optionally with ||{} / ||[])
  for (const m of source.matchAll(/const\s+([a-zA-Z_$][\w$]*)\s*=\s*([a-zA-Z_$][\w$]*)((?:\??\.[a-zA-Z_$][\w$]*)+)/g)) {
    const [, alias, base, chain] = m;
    if (!aliases.has(base)) continue;
    const segs = chain.split(/\??\./).filter(Boolean);
    aliases.set(alias, joinPath(aliases.get(base), segs));
  }
  // ROOT.map(alias=>...) / ROOT.map((alias)=>...) / ROOT.a.b.map(alias=>...)
  for (const m of source.matchAll(/([a-zA-Z_$][\w$.?]*)\.map\(\(?([a-zA-Z_$][\w$]*)\)?\s*=>/g)) {
    const [, chainExpr, alias] = m;
    const parts = chainExpr.split(/\??\./).filter(Boolean);
    const rootTok = parts.shift();
    if (!aliases.has(rootTok)) continue;
    aliases.set(alias, joinPath(joinPath(aliases.get(rootTok), parts), ['*']));
  }
  // destructuring: const {a,b:renamed}=ROOT (only bare/renamed identifiers, no defaults/nesting)
  for (const m of source.matchAll(/const\s*\{([^}]+)\}\s*=\s*([a-zA-Z_$][\w$]*)\s*[;,)]/g)) {
    const [, fields, base] = m;
    if (!aliases.has(base)) continue;
    for (const rawField of fields.split(',')) {
      const f = rawField.trim();
      if (!f || f.includes('...')) continue;
      const [srcName, destName] = f.split(':').map((s) => s.trim());
      if (!srcName) continue;
      aliases.set(destName || srcName, joinPath(aliases.get(base), [srcName]));
    }
  }

  const found = new Set();
  const rootAlt = [...aliases.keys()].sort((a, b) => b.length - a.length)
    .map((v) => v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|');
  if (!rootAlt) return found;
  const chainRe = new RegExp(`\\b(${rootAlt})((?:\\??\\.[a-zA-Z_$][\\w$]*)+)`, 'g');
  for (const m of source.matchAll(chainRe)) {
    const [, base, chain] = m;
    const baseDotted = aliases.get(base);
    const segs = chain.split(/\??\./).filter(Boolean);
    while (segs.length && JS_METHOD_NAMES.has(segs[segs.length - 1])) segs.pop();
    if (!segs.length) continue;
    const full = joinPath(baseDotted, segs);
    if (full) found.add(full);
  }
  return found;
}

/* A path found in source (e.g. "ranked.0.impact.cents" never occurs — array indices in source
   are always the alias-derived ".*") is checked directly against the contract's `nested` map,
   whose keys are already in ".*"-normalized dotted-path form. */
function assertAccessesDeclared(readerName, source, rootVars, extraDeclaredPrefixes = []) {
  const contract = CONTRACTS[readerName];
  assert.ok(contract, `${readerName} must be declared in CONTRACTS`);
  const declared = new Set(Object.keys(contract.nested || {}).filter((k) => k !== '__optional'));
  // A bare intermediate read (e.g. `p.stage_1_to_2` passed whole into ciRateBlockV679, before
  // ciRateBlockV679 pulls .numerator/.denominator/.pct off it) is covered as long as the
  // contract declares at least one deeper path under it — the leaf declarations are what prove
  // the object's real shape; the intermediate read itself invents no new key.
  const isDeclared = (path) => declared.has(path) || [...declared].some((d) => d.startsWith(`${path}.`));
  const accesses = extractAccesses(source, rootVars);
  const undeclared = [...accesses].filter((path) =>
    !isDeclared(path) && !extraDeclaredPrefixes.some((prefix) => path === prefix || path.startsWith(`${prefix}.`)));
  assert.deepStrictEqual(undeclared, [],
    `${readerName}: renderer reads path(s) not declared in CI-READER-CONTRACTS.json nested map: ${undeclared.join(', ')}`);
}

/* --------------------------------------------------------------------------- vm plumbing */

function extractBlock(startMarker, endMarker) {
  const start = appJs.indexOf(startMarker);
  const end = appJs.indexOf(endMarker, start);
  assert.ok(start > -1 && end > start, `could not locate block ${startMarker} .. ${endMarker}`);
  return appJs.slice(start, end);
}

const OPPORTUNITIES_BLOCK = extractBlock(
  'function ciOpportunityConfidenceV685(confidence){',
  'async function serviceMappingBoardPage(){',
);

/* nestly_v723 gap-closure (a): the "revenue truth" v650 quartet — acquisitionMarkupV650,
   ciFunnelStepsMarkupV650+funnelMarkupV650, ciContactabilityGroupMarkupV650+
   contactabilityMarkupV650 — plus their shared helpers (CI_ACQUISITION_VIA_LABELS_V650,
   ciViaLabelV650, ciQuietErrorV650, ciMeasuredSinceV650). All read page-closure `let
   lastXBundle/lastXError` variables rather than taking a payload parameter (see the block's own
   nestly_v650 comment in app/app.js just above CI_ACQUISITION_VIA_LABELS_V650), so the vm
   sandbox supplies those as plain globals instead of rewriting the functions into pure ones. */
const V650_ACQUISITION_FUNNEL_CONTACTABILITY_BLOCK = extractBlock(
  'const CI_ACQUISITION_VIA_LABELS_V650={',
  'const CI_CATEGORY_MIX_READY_THRESHOLD_BPS_V650=9000;',
);

function runBlock(block, exportName, args) {
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
  const money = (c) => 'SGD ' + ((Number(c) || 0) / 100).toFixed(2);
  const walletDate = (v) => String(v ?? '');
  const sandbox = { esc, money, walletDate, console };
  const context = vm.createContext(sandbox);
  context.__exports = {};
  vm.runInContext(`${block}\n__exports.fn = ${exportName};`, context);
  return context.__exports.fn(...args);
}

/* Same idea as runBlock, but for the v650 quartet: it also seeds the page-closure `lastXBundle`/
   `lastXError` globals the block reads instead of passing a fixture as a function argument. */
function runV650Block(exportName, closureVars) {
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
  const walletDate = (v) => String(v ?? '');
  const sandbox = { esc, walletDate, console, ...closureVars };
  const context = vm.createContext(sandbox);
  context.__exports = {};
  vm.runInContext(`${V650_ACQUISITION_FUNNEL_CONTACTABILITY_BLOCK}\n__exports.fn = ${exportName};`, context);
  return context.__exports.fn();
}

