  const contract = CONTRACTS['public.get_ci_funnel_conversion_v1'];
  const fixture = buildFixture(contract.nested, contract.required);
  const html = runBlock(OPPORTUNITIES_BLOCK, 'funnelConversionPanelHtmlV679', [fixture]);
