/* categoryMixMarkupV650 is not a pure function of a payload — it reads
   customerIntelligencePage's own closure variables (lastCategoryMixBundle/lastCategoryMixError/
   expandedCategoryNodesV650/categoryCustomersCacheV650). CATEGORY_MIX_REWRITES lists every
   substitution this test makes to turn it into a pure `(bundle) => html` function so it can be
   executed the same way as its siblings; a reviewer can diff this list against the real function
   to confirm nothing beyond parameter-wiring changed. */
const CATEGORY_MIX_REWRITES = [
  [/\blastCategoryMixError\b/g, 'null'],
  [/const\s+bundle\s*=\s*lastCategoryMixBundle;/, ''],  // bundle is already the parameter
  [/\blastCategoryMixBundle\b/g, 'bundle'],
  [/expandedCategoryNodesV650\.has\([^)]*\)/g, 'false'],
  [/ciCategoryCustomersRowsMarkupV650\([^)]*\)/g, "''"],
];

test('v723 categoryMixMarkupV650 renders the minimal contract fixture cleanly', () => {
  const contract = CONTRACTS['public.get_ci_category_mix_v1'];
  const fixture = buildFixture(contract.nested, contract.required);
  // The renderer's own withhold gate (CI_CATEGORY_MIX_READY_THRESHOLD_BPS_V650, real value 9000)
  // would otherwise fire on the generic leafValue(1) for classified_pct_bps and short-circuit
  // before touching categories/distribution — raise it here so the categories table branch,
  // not just the withheld-state branch, is actually exercised by this fixture.
  fixture.coverage.classified_pct_bps = 9500;

  const fnStart = appJs.indexOf('function categoryMixMarkupV650(){');
  const fnEnd = appJs.indexOf("  function ciCategoryMixWrapV650()", fnStart);
  assert.ok(fnStart > -1 && fnEnd > fnStart, 'categoryMixMarkupV650 must exist as a locatable function');
  let fnSource = appJs.slice(fnStart, fnEnd);
  for (const [pattern, replacement] of CATEGORY_MIX_REWRITES) fnSource = fnSource.replace(pattern, replacement);
  fnSource = fnSource.replace('function categoryMixMarkupV650(){', 'function categoryMixMarkupV650(bundle){');

  const distStart = appJs.indexOf('function ciCategoryDistributionRowMarkupV704(category){');
  const distEnd = appJs.indexOf('function categoryMixMarkupV650(){');
  const distSource = appJs.slice(distStart, distEnd);

  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
  const scopeMoney = (c) => 'SGD ' + ((Number(c) || 0) / 100).toFixed(2);
  const ciMeasuredSinceV650 = (since) => (since ? `<p>Measured since ${esc(since)}</p>` : '');
  const CI_CATEGORY_DISTRIBUTION_FLOOR_V704 = 5;
  // Real value at app/app.js:49450 — categoryMixMarkupV650 reads it directly (module scope, not
  // passed as a parameter), so the sandbox must supply the same constant.
  const CI_CATEGORY_MIX_READY_THRESHOLD_BPS_V650 = 9000;
  const sandbox = {
    esc, scopeMoney, ciMeasuredSinceV650, CI_CATEGORY_DISTRIBUTION_FLOOR_V704,
    CI_CATEGORY_MIX_READY_THRESHOLD_BPS_V650, console,
  };
  const context = vm.createContext(sandbox);
  context.__exports = {};
  vm.runInContext(`${distSource}\n${fnSource}\n__exports.fn = categoryMixMarkupV650;`, context);
  const html = context.__exports.fn(fixture);

  assert.ok(typeof html === 'string' && html.length > 0);
  assert.ok(!/\bundefined\b/.test(html), `renders "undefined": ${html.slice(0, 4000)}`);
  assert.ok(!/\bNaN\b/.test(html), `renders "NaN": ${html.slice(0, 4000)}`);
});

