test('v723 CONTRACT: opportunitiesPanelHtmlV685 + ciOpportunityCardHtmlV685 read only contract-declared paths', () => {
  const src = extractBlock('function ciOpportunityConfidenceV685(confidence){', 'function ciMeasuredSinceInlineV679(');
  /* `impact`, `confidence`, `action` are destructured straight off `item` at the top of
     ciOpportunityCardHtmlV685 (`const action=item?.action||{},confidence=item?.confidence||{},
     impact=item?.impact||{};`) — extractAccesses' alias-assignment pass resolves these from the
     literal source, so no extra root vars are needed beyond `payload`/`item`. */
  /* `payload.error`/`payload.error.message` is opportunitiesPanelHtmlV685's own defensive guard
     against a client-constructed error wrapper (never a shape the real RPC emits — a failed RPC
     call never reaches this renderer at all; see ciFunnelConversionMarkupV679's sibling wiring
     one screen up, which intercepts lastOpportunitiesError before this pure function is called),
     so it is an allowed extra prefix rather than a contract gap. */
  assertAccessesDeclared('public.get_ci_opportunities_v1', src, {payload:'', item:'ranked.*'}, ['error']);
});

